def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]):
    # Initialize the grid with 0s
    grid = [[0] * N for _ in range(N)]

    # Add the values to the grid
    for x, y, value in grid_values:
        grid[y][x] = value

    # Create a 2D list to store the maximum values on each path
    max_values = [[0] * N for _ in range(N)]

    # Loop through each row and column
    for i in range(N):
        for j in range(N):
            # If the current cell is not 0, check if it's a path start
            if grid[i][j] != 0:
                # Calculate the maximum value on the current path
                max_values[i][j] = grid[i][j] + max(max_values[i-1][j-1], max_values[i-1][j], max_values[i][j-1])

    # Return the maximum value on the two paths
    return max(max_values[N-1][N-1], max_values[N-1][0], max_values[0][N-1])
