def max_product(num_str, N, K):
    nums = list(map(int, num_str))
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    for i in range(N):
        for k in range(1, K + 1):
            dp[i][k] = max(dp[i][k - 1], nums[i] * dp[i + 1][k - 1])

    return dp[0][K]
