def count_sequences(n, last, memo):
    if n > last // 2:
        return 0
    if n == last:
        return 1
    if (n, last) in memo:
        return memo[(n, last)]
    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n + i, last, memo)
    memo[(n, last)] = count
    return count
