def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        b = y0 // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count
