def generate_numbers(n, rules):
    num_digits = len(str(n))
    if num_digits == 1:
        return 1
    else:
        seen = set()
        queue = [n]
        while queue:
            num = queue.pop(0)
            for digit in str(num):
                for rule in rules:
                    if digit == rule[0]:
                        new_num = num.replace(digit, rule[1], 1)
                        if new_num not in seen:
                            seen.add(new_num)
                            queue.append(new_num)
        return len(seen)

def catalan_number(n: int) -> int:
    """
    Calculate the nth Catalan number using dynamic programming.

    :param n: The position in the Catalan number sequence to compute (must be non-negative).
    :return: The nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return 1
    else:
        return sum(catalan_number(i) * catalan_number(n-i-1) for i in range(n))

