def min_remaining_space(V, n, volumes):
    # Create a two-dimensional array to store the maximum volume that can be occupied by a subset of the items
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Initialize the first row and column of the array
    for i in range(V + 1):
        dp[i][0] = 0
    for j in range(1, n + 1):
        dp[0][j] = float("inf")

    # Fill in the rest of the array using the dynamic programming approach
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if i - volumes[j - 1] >= 0:
                dp[i][j] = min(dp[i][j], dp[i - volumes[j - 1]][j - 1])
            dp[i][j] = min(dp[i][j], dp[i][j - 1] + volumes[j - 1])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[V][n]
